with httpx.Client(timeout=30) as c:
 r=c.get(state['review_url']);r.raise_for_status();links=set(re.findall(r'(?:src|href)="([^"]+)"',r.text));codes={x:c.head(state['review_url']+x).status_code for x in links};assert all(v==200 for v in codes.values());print(state['review_url'],codes)
